#pragma GCC optimize(2)
#include <cstdio>
#include <iostream>
#define LL long long
using namespace std;

LL a, b, p, x;

LL QuickPow(LL base, LL exp, LL mod) {
    base %= mod;
    LL res = 1;
    while (exp) {
        if (exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

LL Inv(LL val) { return QuickPow(val, p-2, p); }

// Extended gcd to solve CRT
LL extgcd(LL a, LL b, LL &x, LL &y) {
    if (!b) { x=1; y=0; return a; }
    LL x1,y1;
    LL g = extgcd(b, a%b, x1, y1);
    x = y1; y = x1 - (a/b)*y1;
    return g;
}

int main() {
    scanf("%lld%lld%lld%lld", &a, &b, &p, &x);
    LL period = p * (p-1);
    LL ans = 0;
    // For each residue mod (p-1): i in [0, p-2], a^n ≡ a^i (mod p)
    // For each residue mod p: j in [1, p-1] (n>0, n not ≡ 0 mod p since b!=0)
    // Need j * a^i ≡ b (mod p)
    // Then find n ≡ r (mod period) by CRT: n ≡ i (mod p-1), n ≡ j (mod p)
    for (LL i = 0; i < p-1; i++) {
        LL ai = QuickPow(a, i, p);
        // j = b * inv(ai) mod p
        LL j = b * Inv(ai) % p;
        if (j == 0) continue; // n can't be ≡ 0 mod p if b != 0
        // CRT: n ≡ i (mod p-1), n ≡ j (mod p)
        // since gcd(p-1, p) = 1, unique solution mod p*(p-1)
        LL x1, y1;
        extgcd(p-1, p, x1, y1);
        // r = i + (p-1) * ((j-i)*x1 % p)
        LL r = i + (p-1) % period * (((j - i) % p * x1 % p + p) % p) % period;
        r = ((r % period) + period) % period;
        if (r == 0) r = period;
        if (r <= x) ans += (x - r) / period + 1;
    }
    printf("%lld\n", ans);
    return 0;
}

