```cpp
#include <bits/stdc++.h>
using namespace std;
#define maxn 8

pair<int, int> p[maxn];
vector<int> x, y;
set<int> sx, sy;

int main() {
    int i;
    for (i = 0; i < maxn; i++) {
        scanf("%d %d", &p[i].first, &p[i].second);
        if (sx.find(p[i].first) == sx.end()) {
            sx.insert(p[i].first);
            x.push_back(p[i].first);
        }
        if (sy.find(p[i].second) == sy.end()) {
            sy.insert(p[i].second);
            y.push_back(p[i].second);
        }
    }
    if (x.size() != 3 || y.size() != 3) {
        printf("ugly");
        return 0;
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    // Check that the center point is not present
    for (i = 0; i < maxn; i++)
        if (p[i].first == x[1] && p[i].second == y[1]) {
            printf("ugly");
            return 0;
        }

    // Check that all 8 expected points are present
    set<pair<int,int>> pts(p, p + maxn);
    for (int xi = 0; xi < 3; xi++) {
        for (int yj = 0; yj < 3; yj++) {
            if (xi == 1 && yj == 1) continue;
            if (pts.find({x[xi], y[yj]}) == pts.end()) {
                printf("ugly");
                return 0;
            }
        }
    }

    printf("respectable");
