#include<iostream>
#include<cstdio>
#include<algorithm>
#define ll long long
using namespace std;

ll C3(ll n) { // C(n+3,3) = (n+1)(n+2)(n+3)/6
    if (n < 0) return 0;
    return (n+1)*(n+2)*(n+3)/6;
}

ll sumS(ll maxS) { // sum_{s=0}^{maxS} (s+1) = (maxS+1)(maxS+2)/2
    if (maxS < 0) return 0;
    return (maxS+1)*(maxS+2)/2;
}

int main() {
    ll a[3], L;
    for (int i = 0; i < 3; i++) cin >> a[i];
    cin >> L;

    ll total = C3(L);
    ll invalid = 0;

    for (int i = 0; i < 3; i++) {
        ll D = a[(i+1)%3] + a[(i+2)%3] - a[i]; // need x - y - z >= D
        // For each t from 0 to L:
        // maxS = floor((t-D)/2), count += sumS(maxS)
        // Sum over t=0..L of sumS(floor((t-D)/2))
        for (ll t = 0; t <= L; t++) {
            ll maxS = (t - D) / 2;
            if (t - D < 0) maxS = -1; // floor of negative
            if (t < D) maxS = -1;
            else maxS = (t - D) / 2;
            invalid += sumS(maxS);
        }
    }

    cout << total - invalid << endl;
    return 0;
}
