#include <iostream>
#include <vector>
#include <stack>

#define M 100100
#define pb push_back

using namespace std;

long n,m;
vector<long> g[M],d[M],f(M);
vector<bool> u(M,0),c(M,0),t(M,0);

void dfs(long start){
    stack<long> st;
    st.push(start);
    while(!st.empty()){
        long v=st.top(); st.pop();
        if(c[v]) continue;
        c[v]=1; u[v]=1;
        for(long nb: g[v]) if(!u[nb]) st.push(nb);
    }
}

void dfs1(long start){
