The brute force approach is simple and correct for n≤100. Let me implement that:

```cpp
#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    int a[105];
    for (int i = 1; i <= n; i++)
        scanf("%d", &a[i]);

    int best = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j++) {
            // flip [i,j] and count
            int count = 0;
            for (int k = 1; k <= n; k++) {
                int val = a[k];
                if (k >= i && k <= j) val = 1 - val;
                if (val == 1) count++;
            }
            if (count > best) best = count;
        }
    }
    printf("%d\n", best);
    return 0;
}
