Wait, let me simplify this more cleanly:

```cpp
#include <iostream>
#include <algorithm>

int main() {
    int n, m, a, b;
    std::cin >> n >> m >> a >> b;

    int ans = n * a; // worst case: all single tickets

    // Try k m-ride tickets, k from 0 to ceil(n/m)
    int max_k = (n + m - 1) / m;
    for (int k = 0; k <= max_k; k++) {
        int cost = k * b;
        int remaining = n - k * m;
        if (remaining > 0) {
            cost += remaining * a;
        }
        ans = std::min(ans, cost);
    }

    std::cout << ans << std::endl;
    return 0;
}
