    int maxleft = n+2;
    vector<vector<array<ll,2>>> dp(2, vector<array<ll,2>>(maxleft+2, {0LL,0LL}));

    dp[0][0][0] = 1;

    for(int len=1; len<=2*n+1; len++){
        int cur = len%2, prv = 1-cur;
        for(int left=0; left<=n; left++)
            dp[cur][left][0] = dp[cur][left][1] = 0;

        for(int left=0; left<=n; left++){
            for(int used=0; used<=1; used++){
                ll val = dp[prv][left][used];
                if(!val) continue;
                // open event: left increases
                if(left+1 <= n)
                    dp[cur][left+1][used] = (dp[cur][left+1][used] + val) % MOD;
                // close event: left decreases (left must be >0), multiplied by left
                if(left > 0)
                    dp[cur][left-1][used] = (dp[cur][left-1][used] + val % MOD * left) % MOD;
                // interval event: only if used==0 and left>=k
                if(used==0 && left >= k)
                    dp[cur][left][1] = (dp[cur][left][1] + val) % MOD;
            }
        }
    }

    ll ans = dp[(2*n+1)%2][0][1] % MOD;
    ans = ans * power(2, n, MOD) % MOD;

    ll fac = 1;
    for(int i=n+1; i<=2*n+1; i++) fac = fac * i % MOD;
    ans = ans % MOD * inv(fac) % MOD;
    ans = ans * (l % MOD) % MOD;

    printf("%lld\n", ans);
    return 0;
}
