            events[m + 2 * i + 1] = new Event(r, Event.CLOSE_TYPE);
        }
        Arrays.sort(events);
        int[] cnt = new int[m];
        int balance = 0;
        for (Event curEvent : events) {
            if (curEvent.type == Event.OPEN_TYPE) balance++;
            else if (curEvent.type == Event.CLOSE_TYPE) balance--;
            else cnt[curEvent.x - 1] = balance;
        }
        int[] lenUp = getLens(cnt);
        int[] newCnt = new int[cnt.length];
        for (int i = 0; i < cnt.length; i++) newCnt[i] = cnt[cnt.length - i - 1];
        int[] lenDown = getLens(newCnt);
        int[] revLenDown = new int[lenDown.length];
        for (int i = 0; i < lenDown.length; i++) revLenDown[i] = lenDown[lenDown.length - i - 1];
        int max = 0;
        for (int i = 0; i < m; i++) {
            int cur = lenUp[i] + revLenDown[i] - 1;
            max = Math.max(max, cur);
        }
        out.print(max);
    }

