  private Integer[] build(int[] a, int lo, int hi, int m)
  {      
      int n = hi - lo + 1;
      int S = (1 << n);
      Integer[] ans = new Integer[S-1];
      int k = 0;
      for (int i = 1; i < S; i++)
      {
          int sum = 0;   
          for (int j = 0; j < n; j++)
          {
              if (((i >>> j) & 1) != 0){
                  //pick current location
                  sum += a[j+lo];
                  if (sum >= m) sum -= m;
              }
          }
          ans[k++] = sum;
      }
      Arrays.sort(ans);
      return ans;
  }

