import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] argv) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken()) % m;
        int mid = n / 2;
        long[] L = build(a, 0, mid, m);
        long[] R = build(a, mid, n - mid, m);
        long max = 0;
        int j = R.length - 1;
        for (int i = 0; i < L.length; i++) {
            long tgt = m - 1 - L[i];
            while (j >= 0 && R[j] > tgt) j--;
            if (j >= 0) max = Math.max(max, L[i] + R[j]);
            max = Math.max(max, (L[i] + R[R.length - 1]) % m);
        }
        System.out.println(max);
    }

    static long[] build(long[] a, int start, int len, long m) {
        int S = 1 << len;
        long[] ans = new long[S];
        for (int i = 0; i < S; i++) {
            long sum = 0;
            for (int j = 0; j < len; j++)
                if (((i >> j) & 1) == 1) { sum += a[start + j]; if (sum >= m) sum -= m; }
            ans[i] = sum;
        }
        Arrays.sort(ans);
        return ans;
    }
}
