        int rook;
        if (r1 == r2 || c1 == c2) {
            rook = 1;
        } else {
            rook = 2;
        }

        // Bishop
        int bishop;
        if ((r1 + c1) % 2 != (r2 + c2) % 2) {
            bishop = 0;
        } else if (Math.abs(r2 - r1) == Math.abs(c2 - c1)) {
            bishop = 1;
        } else {
            bishop = 2;
        }

        // King
        int king = Math.max(Math.abs(r2 - r1), Math.abs(c2 - c1));

        System.out.println(rook + " " + bishop + " " + king);
    }
}
