        while (pos <= n) {
            // Option 1: fix pos (P[pos] = pos), then remaining = n - pos positions
            long countFixed = (n - pos >= 0) ? dp[n - pos] : 0;
            if (k <= countFixed) {
                result[pos] = pos;
                pos++;
            } else {
                // Option 2: swap pos and pos+1
                k -= countFixed;
                result[pos] = pos + 1;
                result[pos + 1] = pos;
                pos += 2;
