        long n = Long.parseLong(st.nextToken());

        List<Long> primes = new ArrayList<>();
        long temp = x;
        for (long i = 2; i * i <= temp; i++) {
            if (temp % i == 0) {
                primes.add(i);
                while (temp % i == 0) temp /= i;
            }
        }
        if (temp > 1) primes.add(temp);

        long ans = 1;
        long phi = MOD - 1; // MOD is prime, phi(MOD) = MOD-1

        for (long p : primes) {
            // compute sum of floor(n/p^k) for k=1,2,...
            long exp = 0;
            long pk = p;
            while (pk <= n) {
                exp = (exp + (n / pk) % phi) % phi;
                if (pk > n / p) break; // prevent overflow
                pk *= p;
            }
            ans = ans * powMod(p, exp, MOD) % MOD;
        }

        System.out.println(ans);
    }

    static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
