fscanf(STDIN , "%d" , $n);
$a = explode(" " , trim(fgets(STDIN)));
$s = array();
$s[0] = 0;
for($i=1;$i<=$n;$i++) $s[$i] = $s[$i-1] + $a[$i-1];
$ans = -1;
for($i=1;$i<=$n;$i++)
    for($j=$i;$j<=$n;$j++) {
        $t = $s[$n] - ($s[$j] - $s[$i-1])*2 + ($j-$i+1);
        if($t > $ans) $ans = $t;
    }
echo $ans;

